-- ============================================================
-- 全自动化舆情监测研判报送平台 菜单初始化（RuoYi-Vue-Plus v6）
-- sys_menu 共 22 列，INSERT 必须严格按列顺序提供 22 个值
-- 列顺序: menu_id, menu_name, parent_id, order_num, path, component,
--         query_param, is_frame, is_cache, menu_type, visible, status,
--         perms, icon, active_menu, ext, create_dept, create_by,
--         create_time, update_by, update_time, remark
--
-- ID 号段（本模块独占，共 89 个节点）:
--   M 目录 : 1761400000000000900
--   C 菜单 : 1761400000000000901 / 1761400000000000902 / 1761400000000000903 / 1761400000000000904 / 1761400000000000905 / 1761400000000000906 / 1761400000000000907 / 1761400000000000908 / 1761400000000000909 / 1761400000000000910 / 1761400000000000911 / 1761400000000000912 / 1761400000000000913
--   F 按钮 : 每菜单独占 10 号段，按钮 = btnBase + 序号:
--            统计看板 1761400000000006011-1761400000000006013 / 监测任务 1761400000000006021-1761400000000006025 / 关键词库 1761400000000006031-1761400000000006036 / 采集渠道 1761400000000006041-1761400000000006050 / 舆情台账 1761400000000006051-1761400000000006056 / 预警管理 1761400000000006061-1761400000000006066 / 推送管理 1761400000000006071-1761400000000006075 / 报告管理 1761400000000006081-1761400000000006087 / 报告模板 1761400000000006091-1761400000000006095 / 知识库 1761400000000006101-1761400000000006109 / 运行监控 1761400000000006111-1761400000000006113 / 净化批次 1761400000000006121-1761400000000006126 / 研判中心 1761400000000006131-1761400000000006134
--
-- 本脚本可重复执行：先清理本号段的菜单与角色关联，再重新插入
-- ============================================================

-- 清理旧数据（两段号段：C 菜单段 + F 按钮段），保证幂等
DELETE FROM sys_role_menu WHERE menu_id BETWEEN 1761400000000000900 AND 1761400000000000913;
DELETE FROM sys_menu      WHERE menu_id BETWEEN 1761400000000000900 AND 1761400000000000913;
DELETE FROM sys_role_menu WHERE menu_id BETWEEN 1761400000000006011 AND 1761400000000006139;
DELETE FROM sys_menu      WHERE menu_id BETWEEN 1761400000000006011 AND 1761400000000006139;


-- 角色授权：按 role_key 关联超级管理员（v6 的 role_id 并非 1，硬编码会授权失效）
-- 如需授权给其它角色（如「舆情主管」），改 role_key 即可；去掉 WHERE 则授权给全部角色
SELECT r.role_id, m.menu_id
FROM sys_role r
CROSS JOIN sys_menu m
WHERE r.role_key = 'superadmin'
  AND (m.menu_id BETWEEN 1761400000000000900 AND 1761400000000000913
       OR m.menu_id BETWEEN 1761400000000006011 AND 1761400000000006139);

